local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS = game:GetService("UserInputService")
local HttpService = game:GetService("HttpService")
local AssetService = game:GetService("AssetService")
local player = Players.LocalPlayer
if not player then error("BM Forest must run on the local client") end
local playerGui = player:WaitForChild("PlayerGui", 10)
if not playerGui then error("PlayerGui unavailable; enter the game first") end

local GUI_NAME = "BM_Forest_Local_Viewer_v1"
local SCENE_NAME = "BM_Forest_Local_Scene_v1"
local previous = playerGui:FindFirstChild(GUI_NAME)
if previous then
    local signal = previous:FindFirstChild("Shutdown")
    if signal and signal:IsA("BindableEvent") then signal:Fire(); task.wait() end
    if previous.Parent then previous:Destroy() end
end
local leftover = workspace:FindFirstChild(SCENE_NAME)
if leftover then leftover:Destroy() end

local decodedOK, DATA = pcall(function() return HttpService:JSONDecode(RAW_DATA) end)
RAW_DATA = nil
if not decodedOK then error("BM Forest: embedded model data could not be decoded") end

local gui = Instance.new("ScreenGui")
gui.Name = GUI_NAME
gui.ResetOnSpawn = false
gui.DisplayOrder = 80
gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
gui.Parent = playerGui
local shutdown = Instance.new("BindableEvent")
shutdown.Name = "Shutdown"
shutdown.Parent = gui

local panel = Instance.new("Frame")
panel.Size = UDim2.fromOffset(290, 220)
panel.Position = UDim2.new(0, 14, 0, 70)
panel.BackgroundColor3 = Color3.fromRGB(25, 31, 29)
panel.BackgroundTransparency = 0.08
panel.Active = true
panel.Parent = gui
local corner = Instance.new("UICorner")
corner.CornerRadius = UDim.new(0, 12)
corner.Parent = panel

local function label(text, x, y, w, h, size)
    local t = Instance.new("TextLabel")
    t.BackgroundTransparency = 1
    t.Position = UDim2.fromOffset(x, y)
    t.Size = UDim2.fromOffset(w, h)
    t.TextColor3 = Color3.fromRGB(229, 237, 230)
    t.Font = Enum.Font.Gotham
    t.TextSize = size or 13
    t.TextWrapped = true
    t.TextXAlignment = Enum.TextXAlignment.Left
    t.Text = text
    t.Parent = panel
    return t
end
local title = label("BM  /  FOREST", 14, 8, 220, 28, 16)
title.Active = true
local status = label("เลือกโหมดเพื่อโหลดป่า", 14, 42, 262, 38, 13)
label("FULL: รูปทรงเดิม สีพื้น | LITE: ลดรายละเอียด", 14, 82, 262, 28, 11)
label("เห็นเฉพาะฝั่งเรา • กล้องเท่านั้น • ไม่มี Texture", 14, 178, 262, 34, 11)

local function button(text, x, y, w, h)
    local b = Instance.new("TextButton")
    b.Text = text
    b.Position = UDim2.fromOffset(x, y)
    b.Size = UDim2.fromOffset(w, h)
    b.BackgroundColor3 = Color3.fromRGB(54, 75, 61)
    b.TextColor3 = Color3.new(1, 1, 1)
    b.Font = Enum.Font.Gotham
    b.TextSize = 13
    b.Parent = panel
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, 7)
    c.Parent = b
    return b
end
local close = button("X", 252, 8, 27, 27)
local fullButton = button("FULL", 14, 115, 126, 28)
local liteButton = button("LITE", 150, 115, 126, 28)
local viewButton = button("VIEW / ดูป่า", 14, 148, 126, 28)
local rotateButton = button("หมุน: เปิด", 150, 148, 126, 28)

local connections, meshes = {}, {}
local scene, busy, ready, dead = nil, false, false, false
local viewing, cameraState = false, nil
local job = 0
local angle, rotating = 0, CONFIG.autoRotate
local startingRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
local start = startingRoot and startingRoot.Position or Vector3.new(0, 0, 0)
local origin = Vector3.new(start.X, start.Y + CONFIG.height, start.Z)
local extent = DATA.extent
local focus = origin + Vector3.new(0, extent[2] * CONFIG.scale * 0.4, 0)
local radius = math.max(extent[1], extent[3]) * CONFIG.scale * 0.92
local bindName = "BMForestCamera_" .. tostring(math.floor(os.clock() * 100000))

local function connect(signal, fn)
    local c = signal:Connect(fn)
    connections[#connections + 1] = c
    return c
end
local function tell(text)
    if not dead and status.Parent then status.Text = text end
end
local function restoreCamera()
    viewing = false
    RunService:UnbindFromRenderStep(bindName)
    if cameraState then
        local c = cameraState.camera
        if c and c.Parent and c.CameraType == Enum.CameraType.Scriptable then
            pcall(function()
                c.CameraType = cameraState.kind
                local subject = cameraState.subject
                if not subject or not subject.Parent then
                    subject = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
                end
                c.CameraSubject = subject
                c.CFrame = cameraState.cf
                c.Focus = cameraState.focus
                c.FieldOfView = cameraState.fov
            end)
        end
        cameraState = nil
    end
    if viewButton.Parent then viewButton.Text = "VIEW / ดูป่า" end
end
local function clearScene()
    ready = false
    if scene then scene:Destroy(); scene = nil end
    for _, m in ipairs(meshes) do pcall(function() m:Destroy() end) end
    meshes = {}
end
local function cleanup()
    if dead then return end
    dead = true
    job = job + 1
    restoreCamera()
    clearScene()
    for _, c in ipairs(connections) do c:Disconnect() end
    connections = {}
    DATA = nil
    if gui.Parent then gui:Destroy() end
end
connect(shutdown.Event, cleanup)
connect(close.Activated, cleanup)
connect(gui.Destroying, cleanup)
connect(player.CharacterAdded, function() restoreCamera() end)

local dragInput, dragOrigin, panelOrigin
connect(title.InputBegan, function(input)
    if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
        dragInput, dragOrigin, panelOrigin = input, input.Position, panel.Position
    end
end)
connect(UIS.InputChanged, function(input)
    if dragInput and (input == dragInput or input.UserInputType == Enum.UserInputType.MouseMovement) then
        local delta = input.Position - dragOrigin
        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(800, 600)
        local x = math.clamp(panelOrigin.X.Offset + delta.X, 0, math.max(0, viewport.X - 290))
        local y = math.clamp(panelOrigin.Y.Offset + delta.Y, 0, math.max(0, viewport.Y - 260))
        panel.Position = UDim2.fromOffset(x, y)
    end
end)
connect(UIS.InputEnded, function(input)
    if input == dragInput then dragInput = nil end
end)

local function live(id)
    if dead or id ~= job then error("BM_CANCELLED", 0) end
end
local function pause(id)
    task.wait()
    live(id)
end
local function stylePart(p, color)
    p.Anchored = true
    p.CanCollide = false
    p.CanTouch = false
    p.CanQuery = false
    p.CastShadow = false
    p.Material = Enum.Material.SmoothPlastic
    p.Color = Color3.fromRGB(color[1], color[2], color[3])
end
local function vec(t)
    return Vector3.new(t[1], t[2], t[3])
end
local function vertices(flat)
    local a = {}
    for i = 1, #flat, 3 do
        a[#a + 1] = Vector3.new(flat[i], flat[i + 1], flat[i + 2]) * CONFIG.scale
    end
    return a
end

local function buildFull(id)
    for chunkIndex, chunk in ipairs(DATA.exact) do
        live(id)
        tell("FULL: " .. chunkIndex .. "/" .. #DATA.exact .. " ชุด")
        local mesh = AssetService:CreateEditableMesh()
        if dead or id ~= job then if mesh then mesh:Destroy() end; error("BM_CANCELLED", 0) end
        if not mesh then error("EditableMesh memory budget unavailable") end
        meshes[#meshes + 1] = mesh
        local positions = vertices(chunk.v)
        local ids = {}
        for i, p in ipairs(positions) do
            ids[i] = mesh:AddVertex(p)
            if i % 500 == 0 then pause(id) end
        end
        for i = 1, #chunk.f, 3 do
            mesh:AddTriangle(ids[chunk.f[i]], ids[chunk.f[i + 1]], ids[chunk.f[i + 2]])
            if i % 1500 == 1 then pause(id) end
        end
        local part = AssetService:CreateMeshPartAsync(Content.fromObject(mesh), {
            CollisionFidelity = Enum.CollisionFidelity.Box,
            RenderFidelity = Enum.RenderFidelity.Precise
        })
        if dead or id ~= job then if part then part:Destroy() end; error("BM_CANCELLED", 0) end
        part.Name = chunk.name
        stylePart(part, chunk.color)
        part.DoubleSided = true
        part.CFrame = CFrame.new(origin + vec(chunk.center) * CONFIG.scale)
        part.Parent = scene
        pause(id)
    end
end

local function triangle(a, b, c, color)
    local ab, ac, bc = b - a, c - a, c - b
    local ab2, ac2, bc2 = ab:Dot(ab), ac:Dot(ac), bc:Dot(bc)
    if ab2 > ac2 and ab2 > bc2 then c, a = a, c
    elseif ac2 > ab2 and ac2 > bc2 then a, b = b, a end
    ab, ac, bc = b - a, c - a, c - b
    local normal = ac:Cross(ab)
    if normal.Magnitude < 0.00001 or bc.Magnitude < 0.00001 then return end
    local right, back = normal.Unit, bc.Unit
    local up = back:Cross(right).Unit
    local height = math.abs(ab:Dot(up))
    local lengths = {math.abs(ab:Dot(back)), math.abs(ac:Dot(back))}
    local frames = {CFrame.fromMatrix((a + b) / 2, right, up, back),
                    CFrame.fromMatrix((a + c) / 2, -right, up, -back)}
    for i = 1, 2 do
        if lengths[i] > 0.001 and height > 0.001 then
            local p = Instance.new("WedgePart")
            stylePart(p, color)
            p.Size = Vector3.new(0.025, height, lengths[i])
            p.CFrame = frames[i]
            p.Name = "Ground"
            p.Parent = scene
        end
    end
end
local function buildLite(id)
    local ground = DATA.ground
    local v = vertices(ground.v)
    for i = 1, #ground.f, 3 do
        triangle(origin + v[ground.f[i]], origin + v[ground.f[i + 1]], origin + v[ground.f[i + 2]], ground.color)
        if i % 60 == 1 then tell("LITE: กำลังสร้างพื้น"); pause(id) end
    end
    for i, proxy in ipairs(DATA.proxies) do
        live(id)
        local p = Instance.new("Part")
        stylePart(p, proxy.color)
        local size = vec(proxy.size) * CONFIG.scale
        local position = origin + vec(proxy.center) * CONFIG.scale
        if proxy.kind == "wood" then
            p.Shape = Enum.PartType.Cylinder
            p.Size = Vector3.new(size.Y, math.max(size.X * 0.7, 0.1), math.max(size.Z * 0.7, 0.1))
            p.CFrame = CFrame.new(position) * CFrame.Angles(0, 0, math.pi / 2)
        else
            p.Shape = Enum.PartType.Ball
            p.Size = size
            p.CFrame = CFrame.new(position)
        end
        p.Name = proxy.kind
        p.Parent = scene
        if i % 25 == 0 then tell("LITE: " .. i .. "/" .. #DATA.proxies .. " ชิ้น"); pause(id) end
    end
end
local function loadMode(mode)
    if dead or busy then return end
    busy = true
    job = job + 1
    local id = job
    restoreCamera()
    clearScene()
    scene = Instance.new("Model")
    scene.Name = SCENE_NAME
    scene.Parent = workspace
    task.spawn(function()
        local ok, err = pcall(function()
            if mode == "FULL" then buildFull(id) else buildLite(id) end
        end)
        if dead or id ~= job then return end
        busy = false
        if not ok then
            clearScene()
            warn("BM Forest " .. mode .. ": " .. tostring(err))
            if mode == "FULL" then tell("FULL โหลดไม่ได้: กด LITE เพื่อดูแบบลดรายละเอียด")
            else tell("โหลดไม่สำเร็จ ดูข้อความผิดพลาดใน Console") end
            return
        end
        ready = true
        tell(mode .. " พร้อมแล้ว • สูง " .. CONFIG.height .. " studs • กด VIEW")
    end)
end
connect(fullButton.Activated, function() loadMode("FULL") end)
connect(liteButton.Activated, function() loadMode("LITE") end)
connect(rotateButton.Activated, function()
    rotating = not rotating
    rotateButton.Text = rotating and "หมุน: เปิด" or "หมุน: ปิด"
end)
connect(viewButton.Activated, function()
    if viewing then restoreCamera(); return end
    if busy then tell("รอโหลดเสร็จก่อนครับ"); return end
    if not ready then tell("กด FULL หรือ LITE เพื่อโหลดก่อน"); return end
    local camera = workspace.CurrentCamera
    if not camera then return end
    cameraState = {camera = camera, kind = camera.CameraType, subject = camera.CameraSubject,
        cf = camera.CFrame, focus = camera.Focus, fov = camera.FieldOfView}
    viewing = true
    viewButton.Text = "BACK / กลับเกม"
    camera.CameraType = Enum.CameraType.Scriptable
    camera.FieldOfView = 60
    RunService:BindToRenderStep(bindName, Enum.RenderPriority.Camera.Value + 1, function(dt)
        if dead or not viewing then return end
        if workspace.CurrentCamera ~= camera then restoreCamera(); return end
        if rotating then angle = angle + math.min(dt, 0.1) * 0.15 end
        local offset = Vector3.new(math.cos(angle) * radius, radius * 0.55, math.sin(angle) * radius)
        camera.CFrame = CFrame.lookAt(focus + offset, focus)
        camera.Focus = CFrame.new(focus)
    end)
end)

tell("พร้อม • เริ่มที่ LITE บนมือถือ หรือ FULL เพื่อลองรูปทรงเดิม")
